import{_ as a,C as o,o as n,c as r,a2 as e,E as s}from"./chunks/framework.CHjbm2Wd.js";const f=JSON.parse('{"title":"STK essentials","description":"Build a lunar scenario, propagate an orbit, compute access, and read the reports.","frontmatter":{"title":"STK essentials","description":"Build a lunar scenario, propagate an orbit, compute access, and read the reports."},"headers":[],"relativePath":"foundations/stk.md","filePath":"foundations/stk.md","lastUpdated":1792993690000}'),l={name:"foundations/stk.md"};function d(c,t,h,u,g,m){const i=o("Quiz");return n(),r("div",null,[t[0]||(t[0]=e('<h1 id="stk-essentials" tabindex="-1">STK essentials <a class="header-anchor" href="#stk-essentials" aria-label="Permalink to &quot;STK essentials&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Why this matters</p><p>STK (Systems Tool Kit) is common in lunar and planetary mission studies. Job descriptions mention it because it answers geometry questions quickly: when can the lander see Earth, when is the site lit, what is the access window, and where is the vehicle at a given time. You do not need to become an STK operator. You need to build a scenario, ask a question, and export an answer someone can check.</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul><li>Create a Moon-centered scenario with a vehicle and a landing site.</li><li>Propagate a low lunar orbit and inspect position/velocity in multiple frames.</li><li>Compute access and lighting windows with constraints.</li><li>Export a report and explain what the numbers mean.</li><li>Know when STK is the wrong tool.</li></ul><h2 id="the-mental-model" tabindex="-1">The mental model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The mental model&quot;">​</a></h2><p>STK is a geometry and time engine. Everything you do is one of these:</p><ol><li><strong>Define a scenario</strong> — central body, start/stop time, time step.</li><li><strong>Add objects</strong> — satellite, facility, target, sensor, transmitter, receiver, ground station.</li><li><strong>Give objects motion or a fixed position</strong> — propagator, ephemeris, latitude/longitude/altitude.</li><li><strong>Ask a geometric question</strong> — access, visibility, lighting, coverage, link budget.</li><li><strong>Export the answer</strong> — report, graph, data provider, or a script.</li></ol><p>If you cannot state the question in that vocabulary, the UI will feel like a maze.</p><h2 id="a-minimal-lunar-scenario" tabindex="-1">A minimal lunar scenario <a class="header-anchor" href="#a-minimal-lunar-scenario" aria-label="Permalink to &quot;A minimal lunar scenario&quot;">​</a></h2><ol><li><strong>Create a scenario.</strong> Set the central body to the Moon. Use UTC for the scenario time; note the start/stop epoch.</li><li><strong>Add a satellite.</strong> Start with a simple circular orbit at 100 km altitude, or use an NRHO if you are studying a gateway-like architecture.</li><li><strong>Add a landing site.</strong> Use a facility or target at your chosen selenographic latitude/longitude. Add an altitude relative to the terrain or a reference radius.</li><li><strong>Set the propagator.</strong> Two-body is enough for a first pass. Switch to a higher-fidelity lunar gravity model only when the question needs it.</li><li><strong>Compute access.</strong> Select the satellite and the site, then compute access. Inspect start time, stop time, duration, and gaps.</li><li><strong>Add a constraint.</strong> Add a sun-elevation constraint, a sensor field of view, or a communication link. Compare the access windows.</li><li><strong>Export a report.</strong> Save the report with the scenario file and a note describing the question, assumptions, and STK version.</li></ol><p>Do not start with a full mission. One satellite, one site, one question.</p><h2 id="frames-units-and-time" tabindex="-1">Frames, units, and time <a class="header-anchor" href="#frames-units-and-time" aria-label="Permalink to &quot;Frames, units, and time&quot;">​</a></h2><p>STK will happily show you numbers in a frame you did not intend. Before trusting a report:</p><ul><li>Check the <strong>central body</strong> (Moon, not Earth).</li><li>Check the <strong>time scale</strong> (UTC is the default in the UI; internal ephemerides may use other scales).</li><li>Check the <strong>frame</strong> of every position/velocity report (MCI, MCMF, ENU, body).</li><li>Check <strong>units</strong> (km vs m, degrees vs radians, UTCG vs seconds).</li><li>Check the <strong>epoch</strong> of the scenario and any vehicle ephemeris.</li></ul><p>A report without a frame and epoch is not evidence.</p><h2 id="objects-you-will-actually-use" tabindex="-1">Objects you will actually use <a class="header-anchor" href="#objects-you-will-actually-use" aria-label="Permalink to &quot;Objects you will actually use&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Use</th></tr></thead><tbody><tr><td><strong>Satellite</strong></td><td>Orbiting vehicle, lander during coast, relay</td></tr><tr><td><strong>Facility / target</strong></td><td>Landing site, ground station, hazard point</td></tr><tr><td><strong>Sensor</strong></td><td>Field of view, terrain masking, star tracker geometry</td></tr><tr><td><strong>Transmitter / receiver</strong></td><td>Communication link geometry and budget</td></tr><tr><td><strong>Chain</strong></td><td>End-to-end access through multiple objects</td></tr><tr><td><strong>Coverage</strong></td><td>Grid or region statistics over time</td></tr><tr><td><strong>Astrogator</strong></td><td>Maneuver design and trajectory optimization</td></tr></tbody></table><p>For descent, STK is better at the <strong>approach geometry</strong> than at the last hundred meters. Use it for orbit phasing, lighting, line-of-sight, and communication. Use a 6DOF simulation for terminal descent.</p><h2 id="reports-worth-generating" tabindex="-1">Reports worth generating <a class="header-anchor" href="#reports-worth-generating" aria-label="Permalink to &quot;Reports worth generating&quot;">​</a></h2><ul><li><strong>Access:</strong> start/stop/duration for a site and a vehicle.</li><li><strong>Lighting:</strong> sun elevation/azimuth at the site over the descent window.</li><li><strong>Line of sight:</strong> Earth occultation and relay visibility.</li><li><strong>Coverage:</strong> how much of a landing ellipse or traverse is visible from an asset.</li><li><strong>Orbit ephemeris:</strong> position/velocity in MCI and MCMF at a fixed step.</li><li><strong>Link budget:</strong> received power, margin, and data rate over time.</li></ul><p>Save the report, the scenario, and a short README. A screenshot is not a reproducible result.</p><h2 id="stk-and-flight-software" tabindex="-1">STK and flight software <a class="header-anchor" href="#stk-and-flight-software" aria-label="Permalink to &quot;STK and flight software&quot;">​</a></h2><p>STK is a <strong>ground analysis tool</strong>, not flight code. Its outputs can become:</p><ul><li>reference ephemerides for a simulation,</li><li>access windows for a mission timeline,</li><li>lighting constraints for a descent test case,</li><li>truth data for a navigation study,</li><li>requirements for a sensor field of view.</li></ul><p>Do not embed STK in the flight loop. Do not assume its propagator matches your flight dynamics. Use it to generate test cases and to sanity-check your own model.</p><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><p>Build this scenario and write a one-page note:</p><ul><li>Moon-centered, 24-hour scenario.</li><li>A 100 km circular orbit.</li><li>A landing site at a latitude/longitude of your choice.</li><li>Access between the satellite and the site.</li><li>Sun elevation at the site during the access windows.</li><li>One report exported to CSV and one graph.</li></ul><p>Then answer: <strong>Is the site lit during the access? How long is the longest continuous window? What assumption would change the answer most?</strong></p>',29)),s(i,{question:"You need to know whether a landing site is sunlit during a descent window. Which STK construct is the most direct?",options:"A chain with a transmitter and receiver|A lighting/access constraint on the site over the time window|A 6DOF trajectory optimizer|A coverage grid of the entire Moon",answer:"1",explanation:"A lighting constraint on the site (or a sensor/access with a sun-elevation constraint) directly answers the question. A chain is for multi-object access; coverage is for regional statistics."}),t[1]||(t[1]=e('<h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://help.agi.com/stk/" target="_blank" rel="noreferrer">STK help and tutorials</a> — start with the scenario and access tutorials.</li><li><a href="https://help.agi.com/stk/index.htm#automation/objmodel.htm" target="_blank" rel="noreferrer">STK Object Model</a> — for the Month 3 automation page.</li><li><a href="https://support.agi.com/" target="_blank" rel="noreferrer">AGI/Ansys STK community</a> — licensing, install, and version-specific questions.</li><li><a href="https://naif.jpl.nasa.gov/naif/" target="_blank" rel="noreferrer">NASA SPICE</a> — when you need to check STK geometry against an independent source.</li></ul><p>Next: <a href="./matlab-simulink.html">MATLAB &amp; Simulink essentials</a>.</p>',3))])}const b=a(l,[["render",d]]);export{f as __pageData,b as default};
